import type { RefObject } from "react";
import { useEffect, useState } from "react";
import Avatar3D from "../Avatar3D";
import type { VisemeCue } from "../../avatar/LipSyncController";

type AvatarState = "speaking" | "listening" | "thinking";

interface AvatarInterviewerProps {
  isSpeaking: boolean;
  audioRef: RefObject<HTMLAudioElement | null>;
  visemes?: VisemeCue[];
  avatarState?: AvatarState;
  emotion?: string;
  questionText?: string;
  onStateTransition?: (fromState: AvatarState, toState: AvatarState) => void;
}

export default function AvatarInterviewer({
  isSpeaking,
  audioRef,
  visemes,
  avatarState = "listening",
  emotion = "neutral",
  questionText = "",
  onStateTransition,
}: AvatarInterviewerProps) {
  const [displayState, setDisplayState] = useState<AvatarState>(avatarState);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [pulseEffect, setPulseEffect] = useState(false);

  // Handle state transitions with animation
  useEffect(() => {
    if (displayState !== avatarState) {
      setIsTransitioning(true);
      onStateTransition?.(displayState, avatarState);
      
      // Add pulse effect on state change
      setPulseEffect(true);
      setTimeout(() => setPulseEffect(false), 500);
      
      const timer = setTimeout(() => {
        setDisplayState(avatarState);
        setIsTransitioning(false);
      }, 300);
      
      return () => clearTimeout(timer);
    }
  }, [avatarState, displayState, onStateTransition]);

  // Get display state for indicator
  const getStateDisplay = () => {
    switch (displayState) {
      case "speaking":
        return { icon: "≡ƒöè", text: "Speaking", className: "speaking" };
      case "listening":
        return { icon: "≡ƒƒó", text: "Listening", className: "listening" };
      case "thinking":
        return { icon: "≡ƒƒí", text: "Thinking...", className: "thinking" };
      default:
        return { icon: "≡ƒƒí", text: "Thinking...", className: "thinking" };
    }
  };

  const stateDisplay = getStateDisplay();

  return (
    <div 
      style={{ 
        width: "100%", 
        height: "100%", 
        display: "flex", 
        flexDirection: "column",
        transition: "all 0.3s ease",
      }}
      className={`avatar-interviewer-container ${isTransitioning ? "transitioning" : ""}`}
    >
      {/* State Indicator */}
      <div 
        className={`avatar-state-indicator ${stateDisplay.className} ${pulseEffect ? "pulse" : ""}`}
        style={{
          transition: "all 0.3s ease",
          transform: isTransitioning ? "scale(1.05)" : "scale(1)",
        }}
      >
        <span>{stateDisplay.icon}</span>
        <span>{stateDisplay.text}</span>
      </div>

      {/* 3D Avatar */}
      <div 
        style={{ 
          flex: 1, 
          display: "flex", 
          alignItems: "center", 
          justifyContent: "center",
          transition: "all 0.5s ease",
          filter: isTransitioning ? "brightness(1.1)" : "brightness(1)",
        }}
      >
        <Avatar3D
          isSpeacking={isSpeaking}
          audioRef={audioRef}
          visemes={visemes}
          avatarState={displayState}
          emotion={emotion}
        />
      </div>

      {/* Question Display */}
      <div 
        className="question-display"
        style={{
          transition: "all 0.5s ease",
          opacity: questionText ? 1 : 0.7,
        }}
      >
        {questionText ? (
          <p style={{ margin: 0, fontSize: "0.95rem", lineHeight: 1.6, color: "#334155" }}>
            {questionText}
          </p>
        ) : (
          <div className="typing-indicator">
            <span></span>
            <span></span>
            <span></span>
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface CandidateCameraProps {
  isEnabled?: boolean;
}

export default function CandidateCamera({ isEnabled = true }: CandidateCameraProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hasCamera, setHasCamera] = useState(false);
  const [cameraError, setCameraError] = useState<string>("");
  const [micActive, setMicActive] = useState(false);

  useEffect(() => {
    if (!isEnabled) return;

    async function initCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setHasCamera(true);
          setCameraError("");

          // Check if audio track is active
          const audioTrack = stream.getAudioTracks()[0];
          if (audioTrack) {
            setMicActive(audioTrack.enabled);
          }
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setCameraError("Camera access denied or not available");
        setHasCamera(false);
      }
    }

    initCamera();

    return () => {
      // Cleanup: stop all tracks
      if (videoRef.current?.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach((track) => track.stop());
      }
    };
  }, [isEnabled]);

  return (
    <div style={{ width: "100%", height: "100%", position: "relative" }}>
      {hasCamera ? (
        <>
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="camera-preview"
            style={{
              transform: "scaleX(-1)", // Mirror the video
            }}
          />
          {/* Camera Status */}
          <div className="camera-status">
            <div className="status-item">
              <span className={`status-dot ${micActive ? "active" : "inactive"}`}></span>
              <span>Mic: {micActive ? "Active" : "Muted"}</span>
            </div>
            <div className="status-item">
              <span className="status-dot active"></span>
              <span>Camera: On</span>
            </div>
          </div>
        </>
      ) : (
        <div className="camera-overlay">
          <div style={{ textAlign: "center" }}>
            {cameraError ? (
              <>
                <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>≡ƒô╖</div>
                <div>{cameraError}</div>
              </>
            ) : (
              <>
                <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>ΓÅ│</div>
                <div>Initializing camera...</div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";

interface User {
  id: string;
  email: string;
  name: string;
  role: string;
}

interface AuthContextType {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | null>(null);

const API_BASE_URL = import.meta.env.VITE_API_URL ?? "http://localhost:8000";
const AUTH_UNAUTHORIZED_EVENT = "auth:unauthorized";

interface LoginResponse {
  access_token: string;
  refresh_token: string;
  token_type: string;
  expires_in: number;
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(() => {
    return localStorage.getItem("auth_token");
  });
  const [isLoading, setIsLoading] = useState(true);
  const resetAuthState = useCallback(() => {
    setToken(null);
    setUser(null);
  }, []);

  // Fetch user profile on mount if token exists
  useEffect(() => {
    const initAuth = async () => {
      const storedToken = localStorage.getItem("auth_token");
      if (storedToken) {
        try {
          const response = await fetch(`${API_BASE_URL}/api/auth/me`, {
            headers: {
              Authorization: `Bearer ${storedToken}`,
            },
          });
          if (response.ok) {
            const userData = await response.json();
            setUser({
              id: userData.id,
              email: userData.email,
              name: userData.name,
              role: userData.role,
            });
            setToken(storedToken);
          } else {
            // Token invalid, clear it
            localStorage.removeItem("auth_token");
            resetAuthState();
          }
        } catch {
          localStorage.removeItem("auth_token");
          resetAuthState();
        }
      }
      setIsLoading(false);
    };
    void initAuth();
  }, [resetAuthState]);

  const login = useCallback(async (email: string, password: string) => {
    const formData = new URLSearchParams();
    formData.append("username", email);
    formData.append("password", password);

    const response = await fetch(`${API_BASE_URL}/api/auth/login`, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: formData,
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "Login failed" }));
      throw new Error(error.detail || "Login failed");
    }

    const data: LoginResponse = await response.json();
    const accessToken = data.access_token;

    // Store token
    localStorage.setItem("auth_token", accessToken);
    setToken(accessToken);

    // Fetch user profile
    const userResponse = await fetch(`${API_BASE_URL}/api/auth/me`, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    if (userResponse.ok) {
      const userData = await userResponse.json();
      setUser({
        id: userData.id,
        email: userData.email,
        name: userData.name,
        role: userData.role,
      });
    }
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem("auth_token");
    resetAuthState();
  }, [resetAuthState]);

  useEffect(() => {
    const handleUnauthorized = () => {
      resetAuthState();
    };

    window.addEventListener(AUTH_UNAUTHORIZED_EVENT, handleUnauthorized);
    return () => {
      window.removeEventListener(AUTH_UNAUTHORIZED_EVENT, handleUnauthorized);
    };
  }, [resetAuthState]);

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isLoading,
        login,
        logout,
        isAuthenticated: !!token && !!user,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

// Helper function for authenticated fetch
export async function authFetch<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem("auth_token");
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };

  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE_URL}${path}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    if (response.status === 401) {
      // Token expired or invalid
      localStorage.removeItem("auth_token");
      window.dispatchEvent(new CustomEvent(AUTH_UNAUTHORIZED_EVENT));
      window.location.hash = "#/login";
      throw new Error("Unauthorized");
    }
    const error = await response.json().catch(() => ({ detail: "Request failed" }));
    throw new Error(error.detail || "Request failed");
  }

  return response.json();
}

import { useEffect, useRef, useState, useCallback, useReducer, useMemo } from "react";
import type { VisemeCue } from "../avatar/LipSyncController";
import { interviewReducer, initialState } from "./useInterviewStateMachine";
import type { InterviewState } from "./useInterviewStateMachine";

export type AvatarState = "speaking" | "listening" | "thinking";

export type EvaluationPayload = {
  question_index: number;
  question: string;
  transcript: string;
  evaluation: Record<string, unknown>;
};

export type TranscriptMessage = {
  id: string;
  speaker: "ai" | "candidate";
  text: string;
  timestamp?: Date;
};

type QueuedAudioChunk = {
  audio: ArrayBuffer;
  visemes: VisemeCue[];
};

const WS_BASE_URL = `${import.meta.env.VITE_WS_URL ?? "ws://localhost:8000"}/ws/interview`;
const MAX_RECONNECT_ATTEMPTS = 6;

/**
 * Build the WebSocket URL.
 *
 * Appends:
 *   ?token=<jwt>
 *   &mock_session_id=<id>   (if stored in sessionStorage)
 *
 * The frontend stores mock_session_id in sessionStorage when it calls
 * POST /api/candidate/mock-interview/start so the gateway can link this
 * WebSocket session back to the MockInterview DB row.
 */
function getWebSocketUrl(): string {
  const token = localStorage.getItem("auth_token") ?? "";
  const hash = window.location.hash ?? "";
  const hashQuery = hash.includes("?") ? hash.split("?", 2)[1] ?? "" : "";
  const hashParams = new URLSearchParams(hashQuery);
  const mockSessionIdFromHash = hashParams.get("mock_session_id") ?? "";
  const mockSessionId =
    mockSessionIdFromHash || sessionStorage.getItem("mock_session_id") || "";

  const params = new URLSearchParams();
  if (token) params.set("token", token);
  if (mockSessionId) params.set("mock_session_id", mockSessionId);

  const qs = params.toString();
  return qs ? `${WS_BASE_URL}?${qs}` : WS_BASE_URL;
}

export function useInterview() {
  const socketRef = useRef<WebSocket | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const reconnectTimerRef = useRef<number | null>(null);
  const connectIdRef = useRef(0);
  const reconnectAttemptRef = useRef(0);
  const shouldReconnectRef = useRef(true);
  const inFlightSendRef = useRef(false);
  const socketInitialized = useRef(false);

  const [stage, dispatch] = useReducer(interviewReducer, initialState);
  const stageRef = useRef<InterviewState>(stage);

  const audioRef = useRef<HTMLAudioElement | null>(new Audio());
  const activeObjectUrlRef = useRef<string | null>(null);
  const audioQueueRef = useRef<QueuedAudioChunk[]>([]);
  const pendingVisemesRef = useRef<VisemeCue[] | null>(null);
  const isPlayingQueueRef = useRef(false);

  const [avatarText, setAvatarText] = useState("");
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [totalQuestions, setTotalQuestions] = useState(0);
  const [lastEvaluation, setLastEvaluation] = useState<EvaluationPayload | null>(null);
  const [partialTranscript, setPartialTranscript] = useState("");
  const [finalReport, setFinalReport] = useState<Record<string, unknown> | null>(null);
  const [lastError, setLastError] = useState<string>("");
  const [visemes, setVisemes] = useState<VisemeCue[]>([]);
  const [emotion, setEmotion] = useState("neutral");
  const [transcriptMessages, setTranscriptMessages] = useState<TranscriptMessage[]>([]);

  const isRecording = stage === "LISTENING";

  const avatarState: AvatarState = useMemo(() => {
    if (isSpeaking) return "speaking";
    if (stage === "LISTENING") return "listening";
    if (
      stage === "PROCESSING_RESUME" ||
      stage === "PROCESSING_ANSWER" ||
      stage === "CONNECTING"
    ) {
      return "thinking";
    }
    return "thinking";
  }, [isSpeaking, stage]);

  const addTranscriptMessage = useCallback((speaker: "ai" | "candidate", text: string) => {
    const newMessage: TranscriptMessage = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      speaker,
      text,
      timestamp: new Date(),
    };
    setTranscriptMessages((prev) => [...prev, newMessage]);
  }, []);

  const clearTranscript = useCallback(() => {
    setTranscriptMessages([]);
  }, []);

  useEffect(() => {
    stageRef.current = stage;
  }, [stage]);

  useEffect(() => {
    if (socketInitialized.current) return;
    socketInitialized.current = true;
    connectSocket();

    return () => {
      shouldReconnectRef.current = false;
      if (reconnectTimerRef.current !== null) {
        window.clearTimeout(reconnectTimerRef.current);
      }
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== "inactive") {
        mediaRecorderRef.current.stop();
      }
      mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
      clearAudioQueue();
      socketRef.current?.close(1000, "Component unmounted");
      socketInitialized.current = false;

      // Clean up sessionStorage when the interview page unmounts
      sessionStorage.removeItem("mock_session_id");
    };
  }, []);

  function connectSocket() {
    connectIdRef.current += 1;
    const connectId = connectIdRef.current;
    dispatch({ type: "WS_CONNECTING" });

    const ws = new WebSocket(getWebSocketUrl());
    ws.binaryType = "arraybuffer";
    socketRef.current = ws;

    ws.onopen = () => {
      console.log("WebSocket connected successfully");
      if (connectId !== connectIdRef.current) return;
      reconnectAttemptRef.current = 0;
      setIsConnected(true);
      setLastError("");
      dispatch({ type: "WS_CONNECTED" });
    };

    ws.onmessage = (event) => {
      if (connectId !== connectIdRef.current) return;

      if (event.data instanceof ArrayBuffer) {
        enqueueAudioChunk(event.data);
        return;
      }

      if (typeof event.data !== "string") return;

      let msg: Record<string, unknown>;
      try {
        msg = JSON.parse(event.data);
      } catch {
        setLastError("Received invalid JSON from server.");
        dispatch({ type: "ERROR_OCCURRED" });
        return;
      }

      const type = typeof msg.type === "string" ? msg.type : "";

      if (type === "avatar_sync" || type === "question" || type === "next_question") {
        const text = typeof msg.text === "string" ? msg.text : "";
        const qIndex = Number(msg.question_index ?? 0);

        setAvatarText(text);
        setQuestionIndex(qIndex);
        setTotalQuestions(Number(msg.total_questions ?? 0));

        if (text && qIndex > 0) {
          addTranscriptMessage("ai", text);
        }

        if (qIndex === 1 && stageRef.current === "PROCESSING_RESUME") {
          dispatch({ type: "RESUME_PROCESS_SUCCESS" });
        } else if (qIndex > 0) {
          dispatch({ type: "QUESTION_RECEIVED" });
        }
        return;
      }

      if (type === "avatar_visemes") {
        pendingVisemesRef.current = parseVisemes(msg.visemes);
        return;
      }

      if (type === "emotion_update") {
        setEmotion(typeof msg.emotion === "string" ? msg.emotion : "neutral");
        return;
      }

      if (type === "evaluation") {
        const data = (msg.data ?? null) as EvaluationPayload | null;
        setLastEvaluation(data);
        if (data?.transcript) {
          addTranscriptMessage("candidate", data.transcript);
        }
        setPartialTranscript("");
        dispatch({ type: "EVALUATION_COMPLETE" });
        return;
      }

      if (type === "interview_complete") {
        setFinalReport((msg.report ?? null) as Record<string, unknown> | null);
        dispatch({ type: "INTERVIEW_COMPLETE" });
        shouldReconnectRef.current = false;
        // Clear the stored session id - interview is done
        sessionStorage.removeItem("mock_session_id");
        return;
      }

      if (type === "error") {
        const message = typeof msg.message === "string" ? msg.message : "Server error.";
        setLastError(message);
        dispatch({ type: "ERROR_OCCURRED" });
        return;
      }

      if (type === "server_shutdown") {
        const message =
          typeof msg.message === "string" ? msg.message : "Server is restarting. Reconnecting...";
        setLastError(message);
        dispatch({ type: "RESET" });
        return;
      }

      if (type === "partial_transcript") {
        const text = typeof msg.text === "string" ? msg.text : "";
        setPartialTranscript(text);
        setTranscriptMessages((prev) => {
          const lastMsg = prev[prev.length - 1];
          if (lastMsg && lastMsg.speaker === "candidate") {
            const updated = [...prev];
            updated[updated.length - 1] = { ...lastMsg, text };
            return updated;
          }
          return prev;
        });
        return;
      }

      if (type === "phase") {
        const value = typeof msg.value === "string" ? msg.value : "";
        if (value === "LISTENING") {
          dispatch({ type: "PHASE_LISTENING" });
        } else if (value === "PROCESSING") {
          dispatch({ type: "ANSWER_PROCESSING_START" });
        }
        return;
      }
    };

    ws.onerror = (error) => {
      console.error("WebSocket error:", error);
      if (connectId !== connectIdRef.current) return;
      setLastError("WebSocket error.");
      dispatch({ type: "ERROR_OCCURRED" });
    };

    ws.onclose = (event) => {
      console.log("WebSocket closed:", event.code, event.reason);
      if (connectId !== connectIdRef.current) return;
      setIsConnected(false);

      if (!shouldReconnectRef.current) return;
      if (stageRef.current === "INTERVIEW_COMPLETE") return;

      scheduleReconnect();
    };
  }

  function scheduleReconnect() {
    const attempt = reconnectAttemptRef.current + 1;
    reconnectAttemptRef.current = attempt;

    if (attempt > MAX_RECONNECT_ATTEMPTS) {
      setLastError("Connection lost. Max reconnect attempts reached.");
      dispatch({ type: "ERROR_OCCURRED" });
      return;
    }

    const backoffMs = Math.min(1500 * 2 ** (attempt - 1), 15000);
    const jitterMs = Math.floor(Math.random() * 300);
    const delayMs = backoffMs + jitterMs;

    setLastError(`Connection lost. Reconnecting (attempt ${attempt})...`);
    dispatch({ type: "RESET" });

    if (reconnectTimerRef.current !== null) {
      window.clearTimeout(reconnectTimerRef.current);
    }
    reconnectTimerRef.current = window.setTimeout(() => {
      setQuestionIndex(0);
      setTotalQuestions(0);
      setLastEvaluation(null);
      setAvatarText("Reconnected. Please upload resume again.");
      connectSocket();
    }, delayMs);
  }

  async function uploadResume(file: File) {
    if (stage !== "WAITING_RESUME") {
      console.warn("Cannot upload resume outside of WAITING_RESUME stage");
      return;
    }
    if (inFlightSendRef.current) return;
    if (!socketRef.current || socketRef.current.readyState !== WebSocket.OPEN) {
      setLastError("Socket is not connected.");
      dispatch({ type: "ERROR_OCCURRED" });
      return;
    }

    inFlightSendRef.current = true;
    try {
      dispatch({ type: "RESUME_UPLOAD_START" });
      const fileBytes = await fileToBase64(file);
      socketRef.current.send(
        JSON.stringify({
          type: "resume_upload",
          file_name: file.name,
          file_bytes: fileBytes,
        })
      );
      setLastError("");
    } finally {
      inFlightSendRef.current = false;
    }
  }

  async function startAudioStream() {
    if (stage !== "LISTENING") {
      console.warn("Cannot start audio stream outside of LISTENING stage");
      return;
    }
    if (!socketRef.current || socketRef.current.readyState !== WebSocket.OPEN) {
      setLastError("Socket is not connected.");
      dispatch({ type: "ERROR_OCCURRED" });
      return;
    }
    if (isRecording) return;

    try {
      const permissionStatus = await navigator.permissions.query({
        name: "microphone" as PermissionName,
      });
      if (permissionStatus.state === "denied") {
        setLastError(
          "Microphone access is blocked. Please allow microphone access in your browser settings and refresh the page."
        );
        dispatch({ type: "ERROR_OCCURRED" });
        return;
      }
    } catch {
      // permissions API not supported - proceed
    }

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    mediaStreamRef.current = stream;

    const mimeType = MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
      ? "audio/webm;codecs=opus"
      : "audio/webm";

    const recorder = new MediaRecorder(stream, { mimeType });
    mediaRecorderRef.current = recorder;

    recorder.ondataavailable = async (event) => {
      if (stageRef.current !== "LISTENING") return;
      if (!socketRef.current || socketRef.current.readyState !== WebSocket.OPEN) return;
      if (event.data.size <= 0) return;
      const buffer = await event.data.arrayBuffer();
      socketRef.current.send(buffer);
    };

    recorder.onstop = () => {
      if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
        socketRef.current.send(JSON.stringify({ type: "stream_end" }));
        dispatch({ type: "ANSWER_PROCESSING_START" });
      }
      mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
      mediaStreamRef.current = null;
      mediaRecorderRef.current = null;
    };

    recorder.start(300);
    setPartialTranscript("");
    setLastError("");
  }

  function stopAudioStream() {
    const recorder = mediaRecorderRef.current;
    if (!recorder) return;
    if (recorder.state !== "inactive") {
      recorder.stop();
    }
  }

  function enqueueAudioChunk(audio: ArrayBuffer) {
    const nextVisemes = pendingVisemesRef.current ?? [];
    pendingVisemesRef.current = null;

    audioQueueRef.current.push({ audio, visemes: nextVisemes });
    void playNextQueuedAudio();
  }

  async function playNextQueuedAudio() {
    if (isPlayingQueueRef.current) return;

    const next = audioQueueRef.current.shift();
    if (!next) {
      setIsSpeaking(false);
      setVisemes([]);
      return;
    }

    const audioEl = audioRef.current;
    if (!audioEl) {
      setIsSpeaking(false);
      return;
    }

    isPlayingQueueRef.current = true;
    setIsSpeaking(true);
    setVisemes(next.visemes);

    if (activeObjectUrlRef.current) {
      URL.revokeObjectURL(activeObjectUrlRef.current);
      activeObjectUrlRef.current = null;
    }

    const blob = new Blob([next.audio], { type: "audio/wav" });
    const objectUrl = URL.createObjectURL(blob);
    activeObjectUrlRef.current = objectUrl;

    audioEl.src = objectUrl;
    audioEl.currentTime = 0;

    const continueQueue = () => {
      audioEl.onended = null;
      audioEl.onerror = null;
      isPlayingQueueRef.current = false;
      setIsSpeaking(false);
      if (activeObjectUrlRef.current) {
        URL.revokeObjectURL(activeObjectUrlRef.current);
        activeObjectUrlRef.current = null;
      }
      void playNextQueuedAudio();
    };

    audioEl.onended = continueQueue;
    audioEl.onerror = continueQueue;

    try {
      await audioEl.play();
    } catch {
      continueQueue();
    }
  }

  function clearAudioQueue() {
    audioQueueRef.current = [];
    pendingVisemesRef.current = null;

    const audioEl = audioRef.current;
    if (audioEl) {
      audioEl.pause();
      audioEl.onended = null;
      audioEl.onerror = null;
      audioEl.removeAttribute("src");
      audioEl.load();
    }

    if (activeObjectUrlRef.current) {
      URL.revokeObjectURL(activeObjectUrlRef.current);
      activeObjectUrlRef.current = null;
    }

    isPlayingQueueRef.current = false;
    setIsSpeaking(false);
    setVisemes([]);
  }

  return {
    stage,
    avatarState,
    avatarText,
    isSpeaking,
    isConnected,
    questionIndex,
    totalQuestions,
    partialTranscript,
    isRecording,
    lastEvaluation,
    finalReport,
    lastError,
    audioRef,
    visemes,
    emotion,
    transcriptMessages,
    addTranscriptMessage,
    clearTranscript,
    uploadResume,
    startAudioStream,
    stopAudioStream,
  };
}

async function fileToBase64(file: File): Promise<string> {
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result ?? ""));
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });

  const [, base64] = dataUrl.split(",", 2);
  return base64 ?? "";
}

function parseVisemes(raw: unknown): VisemeCue[] {
  if (!Array.isArray(raw)) return [];

  return raw
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const record = item as Record<string, unknown>;

      const start = Number(record.start);
      const end = Number(record.end);
      const viseme = Number(record.viseme);

      if (!Number.isFinite(start) || !Number.isFinite(end) || !Number.isFinite(viseme)) {
        return null;
      }

      return { start, end, viseme } satisfies VisemeCue;
    })
    .filter((item): item is VisemeCue => item !== null);
}

